				entry,
				`"${learner.questionText}" is not an entry in the shipped bank`,
			).toBeDefined();
			const known = new Set(learner.knownWords);
			expect(
				(entry as BankEntry).words.filter((word) => !known.has(word)),
			).toEqual([]);
		}
	});
});

